#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

void solve(vector<int>& nums, string s) {
    string rev = s;
    reverse(rev.begin(), rev.end());
    int minVal = nums[0], maxVal = nums[0];
    for (int x : nums) {
        minVal = min(minVal, x);
        maxVal = max(maxVal, x);
    }
    int vowels = 0;
    for (char c : s) {
        char lower = tolower(c);
        if (lower=='a'||lower=='e'||lower=='i'||lower=='o'||lower=='u') vowels++;
    }
    cout << rev << "\n" << minVal << " " << maxVal << "\n" << vowels << "\n";
}

int main() {
    vector<int> nums = {4, 2, 9, 7, 1};
    solve(nums, "programming");
    return 0;
}

