import java.util.*;

public class Solution {
    public static void solve(int[] nums, String s) {
        String rev = new StringBuilder(s).reverse().toString();
        int min = nums[0], max = nums[0];
        for (int x : nums) {
            min = Math.min(min, x);
            max = Math.max(max, x);
        }
        int vowels = 0;
        for (char c : s.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) != -1) vowels++;
        }
        System.out.println(rev + "\n" + min + " " + max + "\n" + vowels);
    }
    public static void main(String[] args) {
        solve(new int[]{4, 2, 9, 7, 1}, "programming");
    }
}

