#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

pair<int,int> getFrequencies(vector<int>& nums) {
    unordered_map<int, int> freq;
    for (int x : nums) freq[x]++;
    int maxF = 0, minF = 1e9;
    int maxElem = 1e9, minElem = 1e9;
    for (auto& [val, count] : freq) {
        if (count > maxF || (count == maxF && val < maxElem)) {
            maxF = count;
            maxElem = val;
        }
        if (count < minF || (count == minF && val < minElem)) {
            minF = count;
            minElem = val;
        }
    }
    return {maxElem, minElem};
}

int main() {
    vector<int> nums = {1, 2, 3, 1, 1, 4};
    auto res = getFrequencies(nums);
    cout << res.first << " " << res.second << "\n";
    return 0;
}

