import java.util.*;

public class Solution {
    public static int[] getFrequencies(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int maxF = 0, minF = Integer.MAX_VALUE;
        int maxElem = Integer.MAX_VALUE, minElem = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            int val = e.getKey(), count = e.getValue();
            if (count > maxF || (count == maxF && val < maxElem)) {
                maxF = count; maxElem = val;
            }
            if (count < minF || (count == minF && val < minElem)) {
                minF = count; minElem = val;
            }
        }
        return new int[]{maxElem, minElem};
    }
    public static void main(String[] args) {
        int[] res = getFrequencies(new int[]{1, 2, 3, 1, 1, 4});
        System.out.println(res[0] + " " + res[1]);
    }
}

