bool checkSubsequenceSum(int idx, int sum, int k, vector<int>& nums) {
    if (sum == k) return true;
    if (idx == nums.size() || sum > k) return false;
    if (checkSubsequenceSum(idx + 1, sum + nums[idx], k, nums)) return true;
    return checkSubsequenceSum(idx + 1, sum, k, nums);
}

int main() {
    vector<int> nums = {1, 2, 3, 7, 5};
    cout << (checkSubsequenceSum(0, 0, 12, nums) ? "true" : "false") << "\n";
    return 0;
}

