int xor1ToN(int n) {
    if (n % 4 == 1) return 1;
    if (n % 4 == 2) return n + 1;
    if (n % 4 == 3) return 0;
    return n;
}

int findXOR(int L, int R) {
    return xor1ToN(L - 1) ^ xor1ToN(R);
}

