using namespace std;

class MaxHeap {
    vector<int> h;
    void heapifyUp(int i) {
        while (i > 0 && h[(i - 1) / 2] < h[i]) {
            swap(h[(i - 1) / 2], h[i]);
            i = (i - 1) / 2;
        }
    }
    void heapifyDown(int i) {
        int maxIdx = i, left = 2 * i + 1, right = 2 * i + 2;
        if (left < h.size() && h[left] > h[maxIdx]) maxIdx = left;
        if (right < h.size() && h[right] > h[maxIdx]) maxIdx = right;
        if (maxIdx != i) {
            swap(h[i], h[maxIdx]);
            heapifyDown(maxIdx);
        }
    }
public:
    void insert(int val) { h.push_back(val); heapifyUp(h.size() - 1); }
    int extractMax() {
        int res = h[0];
        h[0] = h.back(); h.pop_back();
        if (!h.empty()) heapifyDown(0);
        return res;
    }
    int getMax() { return h[0]; }
};

int main() {
    MaxHeap heap;
    heap.insert(10); heap.insert(30); heap.insert(20);
    cout << heap.extractMax() << "\n"; // 30
    return 0;
}

