import java.util.*;
public class Solution {
    static class MaxHeap {
        List<Integer> h = new ArrayList<>();
        public void insert(int val) {
            h.add(val);
            int i = h.size() - 1;
            while (i > 0 && h.get((i - 1) / 2) < h.get(i)) {
                Collections.swap(h, (i - 1) / 2, i);
                i = (i - 1) / 2;
            }
        }
        public int extractMax() {
            int res = h.get(0);
            h.set(0, h.get(h.size() - 1)); h.remove(h.size() - 1);
            if (!h.isEmpty()) heapifyDown(0);
            return res;
        }
        void heapifyDown(int i) {
            int maxIdx = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < h.size() && h.get(l) > h.get(maxIdx)) maxIdx = l;
            if (r < h.size() && h.get(r) > h.get(maxIdx)) maxIdx = r;
            if (maxIdx != i) { Collections.swap(h, i, maxIdx); heapifyDown(maxIdx); }
        }
    }
    public static void main(String[] args) {
        MaxHeap mh = new MaxHeap();
        mh.insert(10); mh.insert(30); mh.insert(20);
        System.out.println(mh.extractMax());
    }
}

