void topoSort(int u, vector<vector<pair<int,int>>>& adj, vector<bool>& vis, stack<int>& st) {
    vis[u] = true;
    for (auto& edge : adj[u]) if (!vis[edge.first]) topoSort(edge.first, adj, vis, st);
    st.push(u);
}

vector<int> shortestPathDAG(int V, vector<vector<pair<int,int>>>& adj, int src) {
    vector<bool> vis(V, false);
    stack<int> st;
    for (int i = 0; i < V; i++) if (!vis[i]) topoSort(i, adj, vis, st);
    vector<int> dist(V, 1e9);
    dist[src] = 0;
    while (!st.empty()) {
        int u = st.top(); st.pop();
        if (dist[u] != 1e9) {
            for (auto& edge : adj[u]) {
                int v = edge.first, wt = edge.second;
                if (dist[u] + wt < dist[v]) dist[v] = dist[u] + wt;
            }
        }
    }
    for (int i = 0; i < V; i++) if (dist[i] == 1e9) dist[i] = -1;
    return dist;
}

