def shortest_path_dag(V, adj, src):
    visited = [False] * V
    topo = []
    def dfs(u):
        visited[u] = True
        for v, wt in adj[u]:
            if not visited[v]: dfs(v)
        topo.append(u)
    for i in range(V):
        if not visited[i]: dfs(i)
    dist = [float('inf')] * V
    dist[src] = 0
    for u in reversed(topo):
        if dist[u] != float('inf'):
            for v, wt in adj[u]:
                if dist[u] + wt < dist[v]: dist[v] = dist[u] + wt
    return [d if d != float('inf') else -1 for d in dist]

