#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<int> rabinKarp(string text, string pattern) {
    int n = text.size(), m = pattern.size();
    const long long p = 31, mod = 1e9 + 7;
    long long pPow = 1, patHash = 0, textHash = 0;
    for (int i = 0; i < m; i++) {
        patHash = (patHash * p + (pattern[i] - 'a' + 1)) % mod;
        textHash = (textHash * p + (text[i] - 'a' + 1)) % mod;
        if (i < m - 1) pPow = (pPow * p) % mod;
    }
    vector<int> matches;
    for (int i = 0; i <= n - m; i++) {
        if (patHash == textHash && text.substr(i, m) == pattern) {
            matches.push_back(i);
        }
        if (i < n - m) {
            textHash = (textHash - (text[i] - 'a' + 1) * pPow) % mod;
            if (textHash < 0) textHash += mod;
            textHash = (textHash * p + (text[i + m] - 'a' + 1)) % mod;
        }
    }
    return matches;
}

int main() {
    for (int idx : rabinKarp("ababcababa", "aba")) cout << idx << " ";
    cout << "\n";
    return 0;
}

