string prefixToInfix(string pre) {
    stack<string> st;
    for (int i = pre.size() - 1; i >= 0; i--) {
        char c = pre[i];
        if (isalnum(c)) {
            st.push(string(1, c));
        } else {
            string op1 = st.top(); st.pop();
            string op2 = st.top(); st.pop();
            st.push("(" + op1 + c + op2 + ")");
        }
    }
