#include <iostream>
#include <vector>
#include <queue>
#include <set>
#include <algorithm>
using namespace std;

vector<int> maxCombinations(vector<int>& A, vector<int>& B, int C) {
    sort(A.rbegin(), A.rend());
    sort(B.rbegin(), B.rend());
    priority_queue<pair<int, pair<int, int>>> pq;
    set<pair<int, int>> visited;
    pq.push({A[0] + B[0], {0, 0}});
    visited.insert({0, 0});
    vector<int> result;
    while (C-- && !pq.empty()) {
        auto top = pq.top(); pq.pop();
        result.push_back(top.first);
        int i = top.second.first, j = top.second.second;
        if (i + 1 < A.size() && !visited.count({i + 1, j})) {
            pq.push({A[i + 1] + B[j], {i + 1, j}});
            visited.insert({i + 1, j});
        }
        if (j + 1 < B.size() && !visited.count({i, j + 1})) {
            pq.push({A[i] + B[j + 1], {i, j + 1}});
            visited.insert({i, j + 1});
        }
    }
    return result;
}

int main() {
    vector<int> A = {3, 2}, B = {1, 4};
    for (int x : maxCombinations(A, B, 2)) cout << x << " ";
    cout << "\n";
    return 0;
}

