int floorInBST(TreeNode* root, int X) {
    int floorVal = -1;
    while (root) {
        if (root->val == X) return X;
        if (root->val > X) {
            root = root->left;
        } else {
            floorVal = root->val;
            root = root->right;
        }
    }
    return floorVal;
