#include <iostream>
#include <vector>
using namespace std;

struct TrieNode {
    TrieNode* links[2] = {nullptr, nullptr};
};

class BitTrie {
    TrieNode* root;
public:
    BitTrie() { root = new TrieNode(); }
    void insert(int num) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (!node->links[bit]) node->links[bit] = new TrieNode();
            node = node->links[bit];
        }
    }
    int getMaxXOR(int num) {
        TrieNode* node = root;
        int maxVal = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int opp = 1 - bit;
            if (node->links[opp]) {
                maxVal |= (1 << i);
                node = node->links[opp];
            } else {
                node = node->links[bit];
            }
        }
        return maxVal;
    }
};

int main() {
    BitTrie trie;
    for (int x : {3, 10, 5, 25, 2, 8}) trie.insert(x);
    cout << trie.getMaxXOR(5) << "\n"; // 28
    return 0;
}

